def _fix(x, old, new):
    if isinstance(x, str): return x.replace(old, new)
    if isinstance(x, list): return [_fix(i, old, new) for i in x]
    if isinstance(x, tuple): return tuple(_fix(i, old, new) for i in x)
    return x
